css:
.an-mean .mn-row { display: flex; align-items: flex-end; justify-content: center;
                       gap: .34rem; height: 7rem; }
.mn-row i { width: 1.5rem; height: 100%; transform-origin: bottom;
            transform: scaleY(var(--h));
            border-radius: 3px 3px 0 0; background: #6fa8dc;
            animation: mn-level 4s ease-in-out infinite; }
@keyframes mn-level { 0%,22%   { transform: scaleY(var(--h)); background: #6fa8dc; }
                      48%,72%  { transform: scaleY(.5286);    background: #6fd8a0; }
                      96%,100% { transform: scaleY(var(--h)); background: #6fa8dc; } }
.mn-say { margin-top: .9rem; font: 700 .88rem var(--mono); color: var(--paper); text-align: center; }
.mn-say b { color: #6fd8a0; }
@media (prefers-reduced-motion: reduce) {
  .mn-row i { animation: none; opacity: 1; transform: none; }
}

.an-bayes { width: min(90vw, 20rem, 100%); }
.an-bayes .by-svg { display: block; width: min(66vw, 14rem); height: auto; margin: 0 auto;
                        overflow: visible; }
.by-dot { fill: var(--ink); fill-opacity: .26; }
.by-gold { fill: var(--gold); opacity: 0; animation: by-gold 9.6s linear infinite; }
.by-ring { fill: none; stroke: var(--ink); stroke-width: .9; opacity: 0;
           transform-box: fill-box; transform-origin: center; }
.by-tp .by-ring { animation: by-lit1 9.6s linear infinite; }
.by-fp .by-ring { animation: by-lit2 9.6s linear infinite; }
.by-fn, .by-tn { animation: by-out 9.6s linear infinite; }
.by-tp, .by-fp { transform-box: view-box; transform-origin: 0 0;
                 animation: by-go 9.6s linear infinite; }
.by-lab { font: 600 5.4px var(--mono); text-anchor: middle; fill: var(--dim); opacity: 0;
          animation: by-lab 9.6s linear infinite; }
.by-lab-tp { fill: var(--gold); }
.by-eq { font-size: 7px; fill: var(--ink); }
.by-eq-tp { fill: var(--gold); }
.by-say { position: relative; height: 1.2rem; margin-top: .55rem;
          font: 600 .76rem var(--mono); color: var(--ink); text-align: center; }
.by-say span { position: absolute; left: 0; right: 0; opacity: 0; white-space: nowrap; }
.by-say b { color: var(--gold); font-weight: 700; }
.by-say i { font-style: normal; font-weight: 700; }
.by-s0 { animation: by-s0 9.6s linear infinite; }
.by-s1 { animation: by-s1 9.6s linear infinite; }
.by-s2 { animation: by-s2 9.6s linear infinite; }
.by-s3 { animation: by-s3 9.6s linear infinite; }
.by-s4 { animation: by-s4 9.6s linear infinite; }
@keyframes by-gold { 0%, 10.42% { opacity: 0; } 14.58%, 93.75% { opacity: 1; } 98.44%, 100% { opacity: 0; } }
@keyframes by-lit1 { 0%, 27.08% { opacity: 0; transform: scale(1.9); } 31.25%, 92.71% { opacity: 1; transform: scale(1); } 94.79% { opacity: 0; transform: scale(1); } 100% { opacity: 0; transform: scale(1.9); } }
@keyframes by-lit2 { 0%, 41.67% { opacity: 0; transform: scale(1.9); } 45.83%, 92.71% { opacity: 1; transform: scale(1); } 94.79% { opacity: 0; transform: scale(1); } 100% { opacity: 0; transform: scale(1.9); } }
@keyframes by-lab { 0%, 66.67% { opacity: 0; } 70.83%, 92.71% { opacity: 1; } 93.75%, 100% { opacity: 0; } }
@keyframes by-out { 0%, 56.25% { opacity: 1; } 61.46%, 94.79% { opacity: 0; } 98.44%, 100% { opacity: 1; } }
@keyframes by-go { 0%, 59.38% { transform: translate(0px, 0px); animation-timing-function: ease-in-out; } 67.71%, 93.75% { transform: var(--go); animation-timing-function: ease-in-out; } 98.44%, 100% { transform: translate(0px, 0px); } }
@keyframes by-s0 { 0%, 10.94% { opacity: 1; } 12.19%, 97.92% { opacity: 0; } 100% { opacity: 1; } }
@keyframes by-s1 { 0%, 11.98% { opacity: 0; } 13.54%, 26.04% { opacity: 1; } 27.29%, 100% { opacity: 0; } }
@keyframes by-s2 { 0%, 27.08% { opacity: 0; } 28.65%, 40.62% { opacity: 1; } 41.87%, 100% { opacity: 0; } }
@keyframes by-s3 { 0%, 41.67% { opacity: 0; } 43.23%, 65.62% { opacity: 1; } 66.88%, 100% { opacity: 0; } }
@keyframes by-s4 { 0%, 67.71% { opacity: 0; } 69.27%, 92.71% { opacity: 1; } 93.96%, 100% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .by-gold, .by-tp .by-ring, .by-fp .by-ring, .by-fn, .by-tn, .by-tp, .by-fp, .by-lab,
  .by-s0, .by-s1, .by-s2, .by-s3, .by-s4 { animation: none; }
  .by-gold, .by-ring, .by-lab, .by-say .by-s4 { opacity: 1; }
  .by-fn, .by-tn { opacity: 0; }
  .by-tp, .by-fp { transform: var(--go); }
}

.an-pas { display: grid; place-items: center; }
.an-pas .pa-tri { display: flex; flex-direction: column; align-items: center; gap: .28rem; }
.pa-r { display: flex; gap: .28rem; opacity: 0;
        animation: pa-in .45s ease-out both; animation-delay: calc(.2s + var(--r) * .26s); }
.pa-r i { display: grid; place-items: center; width: 2rem; height: 2rem; border-radius: 50%;
          background: #2a2c27; border: 2px solid #3c4038; font: 700 .82rem var(--mono);
          font-style: normal; color: var(--paper);
          animation: pa-pulse 2.8s ease-in-out infinite;
          animation-delay: calc(1.6s + var(--r) * .16s); }
@keyframes pa-in { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; } }
@keyframes pa-pulse { 0%,100% { border-color: #3c4038; }
                      50%     { border-color: #6fa8dc; color: #cfe6ff; } }
.pa-say { margin-top: .8rem; font: 600 .78rem var(--mono); color: rgb(240 236 224 / .5);
          text-align: center; }
@media (prefers-reduced-motion: reduce) {
  .pa-r, .pa-r i { animation: none; opacity: 1; transform: none; }
}

