.ah-l b+b{height:4.2rem}
.ah-l b+b+b{height:3rem}
.ah-a,.ah-p{display:flex;justify-content:center;gap:.5rem}
.ah-a{margin:1.1rem 0 .2rem;font:700 .72rem var(--mono);color:#f0b45f;animation:ah-say 7s steps(7,jump-end) infinite}
@keyframes ah-say{0%,93%,100%{clip-path:inset(0 100% 0 0)}70%,92%{clip-path:inset(0)}}
.ah-a b,.ah-p u{width:1.1rem;text-align:center}
.ah-p u{height:1.1rem;border-radius:50%;background:#5c544a}
.ah-a b:nth-child(6){color:#6fa8dc}
.ah-p u:nth-child(6){background:#6fa8dc}
@media (prefers-reduced-motion: reduce) {
  .ah-a{animation:none}
}

.mg-m{width:15rem;height:.9rem;border:2px solid #5c544a;border-radius:4px}
.mg-m i{display:block;height:100%;background:#f0b45f;transform-origin:left;animation:mg-up 9s steps(29,jump-end) infinite}
@keyframes mg-up{0%{transform:scaleX(0.0333)}85%,100%{transform:scaleX(1);background:#e06c5a}}
.mg-s{display:flex;width:15rem;margin-top:.3rem}
.mg-s b{flex:2;text-align:left}
.mg-s b+b{flex:1}
.mg-s b b{float:right}
.mg-s,.mg-c{font:.62rem var(--mono);color:#f0ece099;text-align:center}
.mg-t{margin:.7rem 0 .4rem;font:italic 600 .8rem var(--mono);color:var(--paper);text-align:center}
@media (prefers-reduced-motion: reduce) {
  .mg-m i{animation:none}
}

.sy-r{position:relative;width:13rem;height:3.6rem}
.sy-r b,.sy-r s{position:absolute;top:0;bottom:0;width:5rem;background:#2b3a4f;border:2px solid #6fa8dc;animation:sy-lit 4s infinite}
.sy-r b{left:0;border-radius:0 50% 50% 0}
.sy-r s{right:0;border-radius:50% 0 0 50%;animation-delay:1.6s}
.sy-r i{position:absolute;left:4.6rem;top:calc(.7rem + var(--i)*.9rem);padding:.225rem;border-radius:50%;background:#f0b45f;animation:sy-go 4s calc(var(--i)*.15s) infinite}
@keyframes sy-lit{40%{background:#2b3a4f}10%,25%{background:#6fa8dc}}
@keyframes sy-go{0%,18%{opacity:0}22%{opacity:1;transform:none}50%{opacity:1;transform:translateX(3.1rem)}58%,100%{opacity:0;transform:translateX(3.1rem)}}
.sy-s{margin-top:.8rem;font:.72rem var(--mono);color:#f0ece08c;text-align:center}
@media (prefers-reduced-motion: reduce) {
  .sy-r b,.sy-r s,.sy-r i{animation:none;opacity:1}
}

.le-r{position:relative;display:grid;place-items:center;height:5rem}
.le-r b{padding:.7rem 1.1rem;border:2px solid #f0ece099;font:700 .8rem var(--mono);color:var(--paper)}
.le-r i{position:absolute;width:4.6rem;height:4.6rem;border:4px solid #6fd8a0;border-radius:50%}
.le-r .le-2{border-color:#e8862c}
.le-r i,.le-t span{animation:le-on 8s infinite}
.an-lens .le-2{animation-delay:-4s}
@keyframes le-on{0%,45%,100%{opacity:1}50%,95%{opacity:0}}
.le-t{display:grid;margin-top:.8rem;font:.7rem var(--mono);color:#6fd8a0;text-align:center}
.le-t span{grid-area:1/1}
.le-t .le-2{color:#e8862c}
@media (prefers-reduced-motion: reduce) {
  .le-r i,.le-t span{animation:none}
  .le-2{display:none}
}

.an-bin { display: grid; place-items: center; }
.an-bin .bn-row { display: flex; gap: .42rem; }
.bn-row i { width: 1.7rem; height: 2.4rem; border-radius: 5px; background: #241f18;
            border: 2px solid #4a3f2c; font-style: normal;
            animation: bn-count 1.44s steps(1, end) infinite; }
.bn-row i:nth-child(8) { animation-duration: .12s; }
.bn-row i:nth-child(7) { animation-duration: .24s; }
.bn-row i:nth-child(6) { animation-duration: .48s; }
.bn-row i:nth-child(5) { animation-duration: .96s; }
.bn-row i:nth-child(4) { animation-duration: 1.92s; }
.bn-row i:nth-child(3) { animation-duration: 3.84s; }
.bn-row i:nth-child(2) { animation-duration: 7.68s; }
.bn-row i:nth-child(1) { animation-duration: 15.36s; }
@keyframes bn-count {
  0%, 49.9%   { background: #241f18; border-color: #4a3f2c; box-shadow: none; }
  50%, 100%   { background: #f0b45f; border-color: #ffd48a;
                box-shadow: 0 0 12px rgb(240 180 95 / .55); }
}
.bn-say { margin-top: .8rem; font: 600 .7rem var(--mono); letter-spacing: .1em;
          color: rgb(240 236 224 / .5); text-align: center; }
@media (prefers-reduced-motion: reduce) {
  .bn-row i { animation: none; opacity: 1; transform: none; }
  .bn-row i:nth-child(2n) { background: #f0b45f; border-color: #ffd48a; }
}

.an-sort { display: grid; place-items: center; }
.an-sort .so-row { display: flex; align-items: flex-end; gap: .3rem; height: 6rem; }
.so-row i { width: 1.5rem; height: 100%; transform-origin: bottom;
            transform: scaleY(var(--h));
            border-radius: 3px 3px 0 0; background: #6fa8dc;
            animation: so-swap 3.2s cubic-bezier(.5,0,.5,1) infinite;
            animation-delay: calc(var(--i) * .09s); }
@keyframes so-swap {
  0%, 6%    { transform: scaleY(var(--h)); background: #6fa8dc; }
  44%, 60%  { transform: scaleY(calc(.12 + var(--i) * .11)); background: #6fd8a0; }
  98%, 100% { transform: scaleY(var(--h)); background: #6fa8dc; }
}
.so-say { margin-top: .8rem; font: 600 .76rem var(--mono); letter-spacing: .14em;
          color: rgb(240 236 224 / .5); text-align: center; }
@media (prefers-reduced-motion: reduce) {
  .so-row i { animation: none; opacity: 1; transform: scaleY(calc(.12 + var(--i) * .11)); background: #6fd8a0; }
}

.an-fit { --fit-u: #6fa8dc; }
.fit-svg { display: block; width: min(88vw, 21rem); max-width: 100%; height: auto; }
.fit-svg text { font: 700 13px var(--mono); text-anchor: middle; fill: var(--paper); }
.fit-bar { fill: var(--paper); fill-opacity: .1; stroke: var(--paper); stroke-opacity: .6; stroke-width: 1; }
.fit-tk { stroke: var(--paper); stroke-opacity: .4; stroke-width: 1; }
.fit-svg .fit-lab text { font-size: 11px; font-weight: 600; fill-opacity: .75; }
.fit-svg .fit-lab .fit-end { font-weight: 700; fill-opacity: 1; }
.fit-lf { color: color-mix(in srgb, var(--paper) 75%, transparent); }
.fit-wall { stroke: var(--paper); stroke-opacity: .75; stroke-width: 1.2; stroke-dasharray: 2.5 2; }
.fit-ok { stroke: var(--gold); stroke-width: 2; }
.fit-b { fill: var(--fit-u); }
.fit-no { fill: var(--coral); }
.fit-dv { stroke: var(--bg); stroke-opacity: .55; stroke-width: 1.1; }
.fit-svg .fit-bn { fill: var(--bg); }
.fit-svg .fit-bf text { font-size: 10.8px; fill: var(--bg); }
.fit-bf { color: var(--bg); }
.fit-gh { fill: none; stroke: var(--fit-u); stroke-opacity: .9; stroke-width: 1.2; stroke-dasharray: 3 2; }
.fit-svg .fit-n, .fit-svg .fit-n text { fill: var(--gold); }
.fit-svg .fit-n text, .fit-svg .fit-tf { font-size: 11px; }
.fit-svg .fit-tf { fill: var(--coral); }
.fit-fl { stroke: currentColor; stroke-width: 1.2; }
.fit-n { color: var(--gold); }
.fit-svg .fit-say { font-size: 11.5px; }
.fit-svg .fit-sum text { font-size: 17px; }
.fit-svg .fit-sum g text { font-size: 11.5px; }
.fit-svg .fit-g, .fit-svg .fit-g text { fill: var(--gold); }
.fit-svg .fit-u, .fit-svg .fit-u text { fill: var(--fit-u); }
.fit-svg .fit-o { fill-opacity: .55; }
.fit-g { color: var(--gold); }
.fit-u { color: var(--fit-u); }
.fit-pp { transform-box: fill-box; transform-origin: center; }
.fit-s ~ .fit-s, .fit-ot { opacity: 0; }
.fit-s { animation: 36s linear infinite; animation-name: var(--kf); }
.fit-dr, .fit-fd, .fit-ot, .fit-pp { animation: 36s cubic-bezier(.3, .7, .4, 1) infinite; animation-delay: var(--d); }
.fit-dr { animation-name: fit-dr; }
.fit-fd { animation-name: fit-fd; }
.fit-ot { animation-name: fit-ot; }
.fit-pp { animation-name: fit-pp; }
@keyframes fit-s1 { 0%, 26.39% { opacity: 1; } 27.78%, 98.61% { opacity: 0; } 100% { opacity: 1; } }
@keyframes fit-s2 { 0%, 26.39% { opacity: 0; } 27.78%, 48.61% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes fit-s3 { 0%, 48.61% { opacity: 0; } 50%, 76.39% { opacity: 1; } 77.78%, 100% { opacity: 0; } }
@keyframes fit-s4 { 0%, 76.39% { opacity: 0; } 77.78%, 98.61% { opacity: 1; } 100%, 100% { opacity: 0; } }
@keyframes fit-dr { 0%, 70.83% { opacity: 0; transform: translateY(-12px); } 71.67% { opacity: 1; } 72.5%, 100% { opacity: 1; transform: none; } }
@keyframes fit-fd { 0%, 70.83% { opacity: 0; } 72.08%, 100% { opacity: 1; } }
@keyframes fit-ot { 0%, 70.83% { opacity: 1; } 72.22%, 100% { opacity: 0; } }
@keyframes fit-pp { 0%, 70.83% { opacity: 0; transform: scale(.3); } 71.53% { opacity: 1; transform: scale(1.25); } 72.08%, 100% { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .an-fit .fit-s, .an-fit .fit-dr, .an-fit .fit-fd, .an-fit .fit-ot, .an-fit .fit-pp { animation: none; }
}
